/**
 * Sequence mark — monochrome SoT. Decision 26 (colour law), Decision 28 (geometry).
 *
 * TWO VARIANTS, the same three nodes on the same centres:
 *
 *   default  docs/brand/marks/sequence-mark.svg — route 6, node radius 3.5
 *   small    docs/brand/marks/sequence-mark-small.svg — route 8, node radius 5
 *
 * Both are GENERATED by packages/desktop/scripts/make-icon.mjs, which is also
 * what rasterises the app icon's frames, so the site, the desktop title bar and
 * the taskbar cannot drift apart. Edit the numbers there, never these rects.
 *
 * Pass `small` at 20px and below (Decision 28 addendum, 2026-09-17). At that
 * size the full mark's 6-unit route is under a pixel of a 64 viewBox and the
 * renderer resolves it as a grey smear rather than an edge; 8 units clears a
 * pixel, and the wider node radius opens real daylight on the diagonal where
 * the three squares meet corner to corner.
 */
import type { CSSProperties } from 'react';

const FULL = (
  <g fill="currentColor">
    <rect x="11" y="11" width="24" height="6" rx="3" />
    <rect x="29" y="11" width="6" height="24" rx="3" />
    <rect x="29" y="29" width="24" height="6" rx="3" />
    <rect x="47" y="29" width="6" height="24" rx="3" />
    <rect x="5" y="5" width="18" height="18" rx="3.5" />
    <rect x="23" y="23" width="18" height="18" rx="3.5" />
    <rect x="41" y="41" width="18" height="18" rx="3.5" />
  </g>
);

const SMALL = (
  <g fill="currentColor">
    <rect x="10" y="10" width="26" height="8" rx="4" />
    <rect x="28" y="10" width="8" height="26" rx="4" />
    <rect x="28" y="28" width="26" height="8" rx="4" />
    <rect x="46" y="28" width="8" height="26" rx="4" />
    <rect x="5" y="5" width="18" height="18" rx="5" />
    <rect x="23" y="23" width="18" height="18" rx="5" />
    <rect x="41" y="41" width="18" height="18" rx="5" />
  </g>
);

export function BrandMark({
  className = '',
  title,
  style,
  small = false,
}: {
  className?: string;
  title?: string;
  style?: CSSProperties;
  /** Use the small variant — required at 20px and below. */
  small?: boolean;
}) {
  return (
    <svg
      viewBox="0 0 64 64"
      aria-hidden={title ? undefined : true}
      role={title ? 'img' : undefined}
      className={className}
      style={style}
      shapeRendering="geometricPrecision"
    >
      {title ? <title>{title}</title> : null}
      {small ? SMALL : FULL}
    </svg>
  );
}
